def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or v == 0:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == v:
                    for s in (-1, 1):
                        y, x = r, c
                        while 0 <= y < h and 0 <= x < w and grid[y][x] in (bg, v):
                            if grid[y][x] == bg:
                                out[y][x] = v
                            y += s * dr
                            x += s * dc
    return out
